    std::vector<std::pair<const std::string&, int>> filtered_attrs;
    for (const auto& attr : attributes) {
        if (attr.first == "required_attribute") {
            // Only keep this attribute if it's not null
            if (!component_meta.find(attr.second).is_default()) {
                filtered_attrs.push_back({attr.second, 1});
            }
        }
    }
    return filtered_attrs;
}

